import time, sys, jax, jax.numpy as jnp
def bench(f,*a,n=20):
    f=jax.jit(f); r=f(*a); jax.block_until_ready(r)
    t=time.perf_counter()
    for _ in range(n): r=f(*a)
    jax.block_until_ready(r); return (time.perf_counter()-t)/n*1e3
k0=jax.random.PRNGKey(0)
qkv=jax.random.normal(k0,(8,1024,3072))
def bounds(seq,n): return [(i*seq//n,(i+1)*seq//n) for i in range(n)]
def prep(qkv):
    b,s,_=qkv.shape
    t=qkv.reshape(b,s,3,16,64)
    return t[:,:,0].transpose(0,2,1,3)*0.125, t[:,:,1].transpose(0,2,3,1), t[:,:,2].transpose(0,2,1,3)
def ref(qkv):
    q,k,v=prep(qkv)
    s=q@k
    s=jnp.where(jnp.tril(jnp.ones((1024,1024),dtype=bool)),s,-jnp.inf)
    return jax.nn.softmax(s,-1)@v
def mk(n, variant):
    def f(qkv):
        q,k,v=prep(qkv)
        if variant=='ones':
            v=jnp.concatenate([v,jnp.ones_like(v[...,:1])],-1)
        outs=[]
        for lo,hi in bounds(1024,n):
            s=q[:,:,lo:hi]@k[:,:,:,:hi]
            mask=jnp.arange(hi)[None,:]<=jnp.arange(lo,hi)[:,None]
            if variant=='base':
                s=jnp.where(mask,s,-jnp.inf)
                m=jnp.max(s,-1,keepdims=True); e=jnp.exp(s-m)
                outs.append((e/jnp.sum(e,-1,keepdims=True))@v[:,:,:hi])
            elif variant=='post':
                m=jnp.max(jnp.where(mask,s,-jnp.inf),-1,keepdims=True)
                e=jnp.where(mask,jnp.exp(s-m),0.)
                outs.append((e@v[:,:,:hi])/jnp.sum(e,-1,keepdims=True))
            elif variant=='ones':
                m=jnp.max(jnp.where(mask,s,-jnp.inf),-1,keepdims=True)
                e=jnp.where(mask,jnp.exp(s-m),0.)
                o=e@v[:,:,:hi]
                outs.append(o[...,:64]/o[...,64:])
            elif variant=='nomax':
                e=jnp.where(mask,jnp.exp(s),0.)
                outs.append((e@v[:,:,:hi])/jnp.sum(e,-1,keepdims=True))
            elif variant=='scoresonly':
                outs.append(s[...,:64])
        return jnp.concatenate(outs,2)
    return f
print('ref',bench(ref,qkv))
for n in [int(a) for a in sys.argv[1:]]:
    for v in ['base','post','ones','nomax','scoresonly']:
        print(n,v,bench(mk(n,v),qkv),flush=True)
